<?php
if(!defined('ABSPATH'))exit;
function legacyx_register_application_type(){register_post_type('legacyx_application',array('labels'=>array('name'=>'Applications','singular_name'=>'Application','menu_name'=>'Applications','add_new_item'=>'Add Application','edit_item'=>'Edit Application'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-portfolio','supports'=>array('title'),'capability_type'=>'post','map_meta_cap'=>true,'show_in_rest'=>false));}add_action('init','legacyx_register_application_type');
function legacyx_application_boxes(){add_meta_box('legacyx_application_details','Application Details','legacyx_application_render_box','legacyx_application','normal','high');}add_action('add_meta_boxes','legacyx_application_boxes');
function legacyx_application_render_box($post){wp_nonce_field('legacyx_save_application','legacyx_application_nonce');$keys=array('client_id','type','status','requested_amount','provider','deadline','decision','required_documents','advisor_note');$v=array();foreach($keys as $k)$v[$k]=get_post_meta($post->ID,'_legacyx_'.$k,true);$clients=get_posts(array('post_type'=>'legacyx_client','post_status'=>'publish','numberposts'=>-1,'orderby'=>'title','order'=>'ASC'));echo '<p><label style="display:block;font-weight:700;margin-bottom:6px">Client</label><select name="legacyx_application[client_id]" style="width:100%"><option value="">Select Universal Client Profile</option>';foreach($clients as $c){$cid=get_post_meta($c->ID,'_legacyx_client_id',true);echo '<option value="'.esc_attr($c->ID).'" '.selected((string)$v['client_id'],(string)$c->ID,false).'>'.esc_html($c->post_title.' · '.$cid).'</option>';}echo '</select></p><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">';echo '<p><label style="display:block;font-weight:600;margin-bottom:6px">Application Type</label><select style="width:100%" name="legacyx_application[type]">';foreach(array('Funding','Grant','Business Service','Credit','Tax','Organizational','Onboarding','Other') as $o)echo '<option '.selected($v['type'],$o,false).'>'.esc_html($o).'</option>';echo '</select></p>';echo '<p><label style="display:block;font-weight:600;margin-bottom:6px">Status</label><select style="width:100%" name="legacyx_application[status]">';foreach(array('Draft','Preparing','Ready','Submitted','Under Review','Additional Information Requested','Approved','Funded','Awarded','Declined','Withdrawn','Closed') as $o)echo '<option '.selected($v['status'],$o,false).'>'.esc_html($o).'</option>';echo '</select></p>';foreach(array('requested_amount'=>'Requested Amount','provider'=>'Provider / Program','deadline'=>'Deadline','decision'=>'Decision / Outcome') as $k=>$label)echo '<p><label style="display:block;font-weight:600;margin-bottom:6px">'.esc_html($label).'</label><input style="width:100%" name="legacyx_application['.esc_attr($k).']" value="'.esc_attr($v[$k]).'"></p>';echo '</div><p><label style="display:block;font-weight:600;margin-bottom:6px">Required Documents</label><textarea style="width:100%;min-height:80px" name="legacyx_application[required_documents]">'.esc_textarea($v['required_documents']).'</textarea></p><p><label style="display:block;font-weight:600;margin-bottom:6px">Advisor Note</label><textarea style="width:100%;min-height:80px" name="legacyx_application[advisor_note]">'.esc_textarea($v['advisor_note']).'</textarea></p>';}
function legacyx_application_save($id){if(get_post_type($id)!=='legacyx_application'||!isset($_POST['legacyx_application_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_application_nonce'])),'legacyx_save_application')||!current_user_can('edit_post',$id)||!isset($_POST['legacyx_application'])||!is_array($_POST['legacyx_application']))return;$raw=wp_unslash($_POST['legacyx_application']);if(isset($raw['client_id']))update_post_meta($id,'_legacyx_client_id',absint($raw['client_id']));foreach(array('type','status','requested_amount','provider','deadline','decision') as $k)if(isset($raw[$k]))update_post_meta($id,'_legacyx_'.$k,sanitize_text_field($raw[$k]));foreach(array('required_documents','advisor_note') as $k)if(isset($raw[$k]))update_post_meta($id,'_legacyx_'.$k,sanitize_textarea_field($raw[$k]));}add_action('save_post_legacyx_application','legacyx_application_save');
function legacyx_get_client_applications($client_id){return get_posts(array('post_type'=>'legacyx_application','post_status'=>'publish','numberposts'=>-1,'meta_key'=>'_legacyx_client_id','meta_value'=>(string)absint($client_id),'orderby'=>'date','order'=>'DESC'));}
function legacyx_application_counts($client_id){$items=legacyx_get_client_applications($client_id);$out=array('active'=>0,'approved'=>0,'closed'=>0,'total'=>count($items));foreach($items as $item){$s=strtolower((string)get_post_meta($item->ID,'_legacyx_status',true));if(in_array($s,array('approved','funded','awarded'),true))$out['approved']++;elseif(in_array($s,array('closed','declined','denied','withdrawn','completed'),true))$out['closed']++;else$out['active']++;}return $out;}
